package io.knowledgebrain.activity;
import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
record ActivityQuery(long from,long to,String timezone,String kind,int limit,Long before,UUID event,String stamp){
 static ResponseStatusException bad(){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid timeline range, timezone, type, limit or cursor");}
 static ActivityQuery parse(UUID space,Map<String,String[]> params){try{if(!Set.of("from","to","timezone","kind","limit","before").containsAll(params.keySet())||params.values().stream().anyMatch(v->v.length!=1))throw bad();String zone=params.containsKey("timezone")?params.get("timezone")[0]:"UTC";if((params.containsKey("from")||params.containsKey("to"))&&!params.containsKey("timezone"))throw bad();ZoneId timezone=ZoneId.of(zone);String kind=params.containsKey("kind")?params.get("kind")[0]:"ALL";if(!kind.equals("ALL")&&!ActivityEvent.TOPICS.containsKey(kind))throw bad();int limit=params.containsKey("limit")?Integer.parseInt(params.get("limit")[0]):20;if(limit<1||limit>100)throw bad();LocalDate a=params.containsKey("from")?day(params.get("from")[0]):null,z=params.containsKey("to")?day(params.get("to")[0]):null;if(a!=null&&z!=null&&(z.isBefore(a)||java.time.temporal.ChronoUnit.DAYS.between(a,z)>366))throw bad();long from=a==null?0:a.atStartOfDay(timezone).toInstant().toEpochMilli(),to=z==null?Long.MAX_VALUE:z.plusDays(1).atStartOfDay(timezone).toInstant().toEpochMilli();if(from<0||to<=from)throw bad();String stamp=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((space+"|"+from+"|"+to+"|"+zone+"|"+kind).getBytes(StandardCharsets.UTF_8))).substring(0,16);Long before=null;UUID event=null;if(params.containsKey("before")){String raw=params.get("before")[0];if(!raw.matches("[A-Za-z0-9_-]{1,256}"))throw bad();var node=tools.jackson.databind.json.JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build().readTree(Base64.getUrlDecoder().decode(raw));if(!node.isObject()||node.size()!=3||!node.path("stamp").isString()||!node.path("stamp").asString().equals(stamp)||!node.path("millis").isIntegralNumber()||!node.path("millis").canConvertToLong()||!node.path("eventId").isString())throw bad();before=node.path("millis").asLong();event=ActivityEvent.id(node.path("eventId").asString());if(before<from||before>=to)throw bad();}return new ActivityQuery(from,to,zone,kind,limit,before,event,stamp);}catch(ResponseStatusException e){throw e;}catch(Exception e){throw bad();}}
 private static LocalDate day(String s){if(!s.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))throw bad();return LocalDate.parse(s);}
 String cursor(ActivityEvent e){var json=tools.jackson.databind.json.JsonMapper.builder().build();return Base64.getUrlEncoder().withoutPadding().encodeToString(json.writeValueAsBytes(Map.of("stamp",stamp,"millis",Instant.parse(e.occurredAt()).toEpochMilli(),"eventId",e.eventId().toString())));}
}
